func TestOfficePDFRealSpreadsheetAndPresentation(t *testing.T) {
	if _, err := exec.LookPath("bwrap"); err != nil {
		t.Skip("bwrap unavailable")
	}
	if _, err := exec.LookPath("soffice"); err != nil {
		t.Skip("soffice unavailable")
	}
	service, _ := testService(t)
	admin := domain.User{ID: "u_admin", Login: "admin", IsAdmin: true}
	cases := []struct {
		name, kind, term string
		content          []byte
	}{
		{"sample.xlsx", "spreadsheet", "Quarter", testSpreadsheetOOXML(t)},
		{"sample.pptx", "presentation", "Engineering preview slide", testPresentationOOXML(t)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			record, err := service.CommitUpload(context.Background(), admin, "folder_market", tc.name, "application/octet-stream", "", bytes.NewReader(tc.content))
			if err != nil {
				t.Fatal(err)
			}
			preview, err := service.Preview(context.Background(), admin, record.FileID)
			if err != nil || preview.Structured == nil || preview.Structured.Kind != tc.kind {
				t.Fatalf("structured adapter failed: %v %+v", err, preview)
			}
			pdf, err := service.OfficePDFPreview(context.Background(), admin, record.FileID)
			if err != nil {
				t.Fatalf("real Office conversion failed: %v", err)
			}
			if len(pdf) < 500 || !strings.HasPrefix(string(pdf[:8]), "%PDF-") {
				t.Fatalf("invalid PDF length/signature: %d", len(pdf))
			}
		})
	}
}
